    private void UploadCam(){camGpuDirty=false;camVertexCount=camSelectedVertexCount=camFaceVertexCount=camSelectedFaceVertexCount=camEditVertexCount=camEditFaceVertexCount=0;if(camScene==null||!glReady)return;EnsureCam(ref camVao,ref camVbo);EnsureCam(ref camSelectedVao,ref camSelectedVbo);EnsureCam(ref camFaceVao,ref camFaceVbo);EnsureCam(ref camSelectedFaceVao,ref camSelectedFaceVbo);EnsureCam(ref camEditVao,ref camEditVbo);EnsureCam(ref camEditFaceVao,ref camEditFaceVbo);for(int i=0;i<3;i++)EnsureCam(ref camGizmoVaos[i],ref camGizmoVbos[i]);var lines=new List<float>();var selectedLines=new List<float>();var faces=new List<float>();var selectedFaces=new List<float>();foreach(CamEntry e in camScene.Entries)AddCamEntry(e,e.FileOrder==selectedCamEntry?selectedLines:lines,e.FileOrder==selectedCamEntry?selectedFaces:faces);UploadLineBuffer(camVao,camVbo,lines,out camVertexCount);UploadLineBuffer(camSelectedVao,camSelectedVbo,selectedLines,out camSelectedVertexCount);UploadLineBuffer(camFaceVao,camFaceVbo,faces,out camFaceVertexCount);UploadLineBuffer(camSelectedFaceVao,camSelectedFaceVbo,selectedFaces,out camSelectedFaceVertexCount);var axes=new[]{new List<float>(),new List<float>(),new List<float>()};var editLines=new List<float>();var editFaces=new List<float>();CamEntry? selected=SelectedCam();if(selected!=null){AddCamEditHandles(axes,editLines,editFaces,selected);bool hasTarget=CamTransformMode!=CamGizmoMode.Vertex||selectedCamVertex>=0&&selectedCamVertex<selected.Vertices.Count;if(hasTarget){NVector3 c=CamGizmoOrigin(selected);float len=CamGizmoLength(selected);bool horizontalFace=CamTransformMode==CamGizmoMode.Face&&selectedCamFace>=selected.Vertices.Count;if(horizontalFace)AddCamArrow(axes[1],c,selectedCamFace==selected.Vertices.Count?-NVector3.UnitY:NVector3.UnitY,len);else{AddCamArrow(axes[0],c,NVector3.UnitX,len);if(CamTransformMode==CamGizmoMode.Move)AddCamArrow(axes[1],c,NVector3.UnitY,len);AddCamArrow(axes[2],c,NVector3.UnitZ,len);}if(CamTransformMode==Ca