    private static void AddCamTrajectory(List<float> lines,CamEntry entry)
    {
        if(entry.Frames.Count<2)return;
        for(int i=1;i<entry.Frames.Count;i++)
        {
            AddCamPathSegment(lines,CamVectorToWorld(entry.Frames[i-1].Position),CamVectorToWorld(entry.Frames[i].Position));
            AddCamPathSegment(lines,CamVectorToWorld(entry.Frames[i-1].Target),CamVectorToWorld(entry.Frames[i].Target));
        }
    }
    private static void AddCamPathSegment(List<float> lines,NVector3 a,NVector3 b)
    {
        AddCamLine(lines,a,b);NVector3 delta=b-a;if(delta.LengthSquared()<.0001f)return;NVector3 direction=NVector3.Normalize(delta);NVector3 side=NVector3.Cross(direction,NVector3.UnitY);if(side.LengthSquared()<.0001f)side=NVector3.UnitX;else side=NVector3.Normalize(side);float size=Math.Clamp(delta.Length()*.12f,.12f,.5f);AddCamLine(lines,b,b-direction*size+side*size*.45f);AddCamLine(lines,b,b-direction*size-side*size*.45f);
    }
    private void AddCamEditHandles(List<float>[] axes,List<float> selectedLines,List<float> selectedFace,CamEntry e)
    {
        if(e.CameraType is CamType.Track or CamType.Motion)AddCamTrajectory(selectedLines,e);
        if(CamTransformMode==CamGizmoMode.Frame&&selectedCamFrame>=0&&selectedCamFrame<e.Frames.Count){CamFrame frame=e.Frames[selectedCamFrame];NVector3 p=CamVectorToWorld(selectedCamTarget?frame.Target:frame.Position);float s=CamScreenSize(p,16f);AddCamLine(selectedLines,p-new NVector3(s,0,0),p+new NVector3(s,0,0));AddCamLine(selectedLines,p-new NVector3(0,s,0),p+new NVector3(0,s,0));AddCamLine(selectedLines,p-new NVector3(0,0,s),p+new NVector3(0,0,s));AddCamArrow(axes[1],p,NVector3.UnitY,CamGizmoLength(e));return;}
        if(CamTransformMode==CamGizmoMode.Vertex){CamWorldYRange(e,out _,out float y);for(int i=0;i<e.Vertices.Count;i++){NVector3 p=CamToWorld(e.Vertices[i].Position,y);float s=CamScreenSize(p,i==selectedCamVertex?15f:10f);List<float> output=i==selectedCamVertex?selectedLines:axes[1];AddCamLine(output,p-new NVector3(s,0,0),p+new NVector3(s,0,0));AddCamLine(output,p-new NVector3(0,s,0),p+new NVector3(0,s,0));AddCamLine(output,p-new NVector3(0,0,s),p+new NVector3(0,0,s));}}
        else if(CamTransformMode==CamGizmoMode.Face&&selectedCamFace>=0){CamWorldYRange(e,out float y0,out float y1);var b=e.Vertices.Select(v=>CamToWorld(v.Position,y0)).ToArray();var t=e.Vertices.Select(v=>CamToWorld(v.Position,y1)).ToArray();if(selectedCamFace<e.Vertices.Count){int i=selectedCamFace,j=(i+1)%e.Vertices.Count;AddCamQuad(selectedFace,b[i],b[j],t[j],t[i]);AddCamLine(selectedLines,b[i],b[j]);AddCamLine(selectedLines,b[j],t[j]);AddCamLine(selectedLines,t[j],t[i]);AddCamLine(selectedLines,t[i],b[i]);}else{NVector3[] ring=selectedCamFace==e.Vertices.Count?b:t;for(int i=1;i<ring.Length-1;i++)AddCamTriangle(selectedFace,ring[0],ring[i],ring[i+1]);for(int i=0;i<ring.Length;i++)AddCamLine(selectedLines,ring[i],ring[(i+1)%ring.Length]);}}
    }
    private static void EnsureCam(ref int vao,ref int vbo){if(vao==0){vao=GL.GenVertexArray();vbo=GL.GenBuffer();}}
    private static void AddCamEntry(CamEntry e,List<float> lines,List<float> faces){if(e.Vertices.Count>=3){CamWorldYRange(e,out float y0,out float y1);var b=e.Vertices.Select(v=>CamToWorld(v.Position,y0)).ToArray();var t=e.Vertices.Select(v=>CamToWorld(v.Position,y1)).ToArray();for(int i=0;i<b.Length;i++){int j=(i+1)%b.Length;AddCamLine(lines,b[i],b[j]);AddCamLine(lines,t[i],t[j]);AddCamLine(lines,b[i],t[i]);AddCamQuad(faces,b[i],b[j],t[j],t[i]);}for(int i=1;i<b.Length-1;i++){AddCamTriangle(faces,b[0],b[i+1],b[i]);AddCamTriangle(faces,t[0],t[i],t[i+1]);}}foreach(CamFrame f in e.Frames){NVector3 p=CamVectorToWorld(f.Position),t=CamVectorToWorld(f.Target),forward=t-p;if(forward.LengthSquared()<.0001f)forward=NVector3.UnitZ;forward=NVector3.Normalize(forward);NVector3 right=NVector3.Cross(NVector3.UnitY,forward);if(right.LengthSquared()<.0001f)right=NVector3.UnitX;else right=NVector3.Normalize(right);NVector3 up=NVector3.Normalize(NVector3.Cross(forward,right));float s=.42f;NVector3 rear=p-forward*s*.55f;AddCamLine(lines,p,t);AddCamLine(lines,rear-right*s,rear+right*s);AddCamLine(lines,rear-up*s*.7f,rear+up*s*.7f);AddCamLine(lines,rear-right*s,p+forward*s);AddCamLine(lines,rear+right*s,p+forward*s);AddCamLine(lines,rear-up*s*.7f,p+forward*s);AddCamLine(lines,rear+up*s*.7f,p+forward*s);float q=.25f;AddCamLine(lines,t-right*q,t+right*q);AddCamLine(lines,t-up*q,t+up*q);}}
    private void DrawCamGpu(){if(!CamVisible||camScene==null)return;GL.Disable(EnableCap.CullFace);GL.Enable(EnableCap.DepthTest);GL.DepthFunc(DepthFunction.Lequal);GL.DepthMask(false);GL.Uniform1(uUnlit,1);GL.Uniform1(uUseTexture,0);GL.Enable(EnableCap.Blend);GL.BlendFunc(BlendingFactor.SrcAlpha,BlendingFactor.OneMinusSrcAlpha);if(camFaceVertexCount>0){GL.Uniform1(uOpacity,.13f);GL.Uniform3(uColor,.62f,.12f,.92f);GL.BindVertexArray(camFaceVao);GL.DrawArrays(PrimitiveType.Triangles,0,camFaceVertexCount);}if(camSelectedFaceVertexCount>0){GL.Uniform1(uOpacity,.28f);GL.Uniform3(uColor,1f,.65f,.08f);GL.BindVertexArray(camSelectedFaceVao);GL.DrawArrays(PrimitiveType.Triangles,0,camSelectedFaceVertexCount);}if(camEditFaceVertexCount>0){GL.Uniform1(uOpacity,.58f);GL.Uniform3(uColor,.05f,.85f,1f);GL.BindVertexArray(camEditFaceVao);GL.DrawArrays(PrimitiveType.Triangles,0,camEditFaceVertexCount);}GL.Uniform1(uOpacity,1f);GL.Disable(EnableCap.Blend);if(camVertexCount>0){GL.Uniform3(uColor,.75f,.2f,1f);GL.BindVertexArray(camVao);GL.LineWidth(2f);GL.DrawArrays(PrimitiveType.Lines,0,camVertexCount);}if(camSelectedVertexCount>0){GL.Uniform3(uColor,1f,.75f,.12f);GL.BindVertexArray(camSelectedVao);GL.LineWidth(4f);GL.DrawArrays(PrimitiveType.Lines,0,camSelectedVertexCount);}if(camEditVertexCount>0){GL.Uniform3(uColor,.05f,.9f,1f);GL.BindVertexArray(camEditVao);GL.LineWidth(7f);GL.DrawArrays(PrimitiveType.Lines,0,camEditVertexCount);}var colors=new[]{(1f,.15f,.12f),(.2f,.95f,.25f),(.12f,.48f,1f)};for(int i=0;i<3;i++)if(camGizmoCounts[i]>0){GL.Uniform3(uColor,colors[i].Item1,colors[i].Item2,colors[i].Item3);GL.BindVertexArray(camGizmoVaos[i]);GL.LineWidth(5f);GL.DrawArrays(PrimitiveType.Lines,0,camGizmoCounts[i]);}GL.LineWidth(1f);GL.DepthMask(true);GL.Enable(EnableCap.DepthTest);GL.Enable(EnableCap.CullFace);}
    private void DrawCamFrameLabelsGpu()
